const neighborFarms=[
 ['sun','krasnodar','Солнечный двор','Анна','🦊',8,'farm_house_lvl5',['Томаты','Огурцы','Морковь','Зелень'],2,'Семейное хозяйство: овощи к столу и корзины друзьям.'],
 ['green','krasnodar','Зелёный квартал','Михаил','🐻',12,'farm_house_lvl7',['Огурцы','Томаты','Баклажаны'],5,'Теплицы, шпалеры и длинные ряды огурцов.'],
 ['herbs','krasnodar','Пряный сад','Елена','🐰',5,'farm_house_lvl2',['Зелень','Морковь','Томаты'],1,'Небольшой огород с зеленью и сезонными овощами.'],
 ['family','moscow','Дача в кармане','Алексей','🦝',6,'farm_house_lvl5',['Огурцы','Зелень','Томаты'],3,'Уютная семейная ферма с защищёнными посадками.'],
 ['glass','moscow','Под стеклом','Мария','🐱',10,'farm_house_lvl7',['Томаты','Огурцы','Баклажаны'],8,'Большая часть посадок — в теплицах.'],
 ['weekend','moscow','Выходной на грядке','Денис','🐼',4,'farm_house_lvl2',['Морковь','Зелень','Огурцы'],1,'Четыре грядки, свой урожай и регулярные корзины домой.'],
 ['north','petersburg','Северный огород','Ольга','🦉',9,'farm_house_lvl7',['Огурцы','Зелень','Томаты'],6,'Пример хозяйства с акцентом на защищённый грунт.'],
 ['mint','petersburg','Мята и компания','Ирина','🐨',5,'farm_house_lvl5',['Зелень','Огурцы','Морковь'],2,'Зелень, маленькие теплицы и забота о каждой грядке.'],
 ['island','petersburg','Остров урожая','Сергей','🐶',7,'farm_house_lvl5',['Томаты','Огурцы','Баклажаны'],4,'Разные культуры и несколько этапов выращивания одновременно.']
].map(([id,city,name,owner,avatar,count,house,crops,covers,description])=>({id,city,name,owner,avatar,count,house,crops,covers,description}));
const neighborCity=id=>farmLocations.find(c=>c.id===id);
function neighborBeds(f){return Array.from({length:f.count},(_,i)=>({id:i+1,crop:f.crops[i%f.crops.length],state:['harvest_ready','growing','planted','ready'][i%4],covered:i<f.covers,size:i%3===0?7:3}))}
function demoNotice(){return '<div class="neighbor-demo">✦ Демо-мир · вымышленные хозяйства и история за полгода. Это примеры, а не реальные пользователи.</div>'}
function neighborCities(){return heading('Карта ферм','Сначала выберите город, затем загляните в хозяйства.')+demoNotice()+`<div class="neighbor-cities">${farmLocations.map((c,i)=>`<a class="neighbor-city" href="#farms-${c.id}"><img src="art/imported/${['farm_lvl3','farm_house_lvl5','farm_house_lvl7'][i]}.svg" alt=""><small>ПОСМОТРЕТЬ ХОЗЯЙСТВА</small><h2>${c.name}</h2><p>3 демонстрационные фермы</p><b>Выбрать город →</b></a>`).join('')}</div><p class="note">Демо-хозяйства доступны во всех трёх городах. Реальная площадка подключена только в Белореченске.</p>`}
function neighborDirectory(city){const c=neighborCity(city);if(!c)return neighborCities();return `<a class="room-back" href="#farms">← Выбрать другой город</a>`+heading(c.name,'Загляните в гости: посмотрите теплицы, посадки и историю сезона.')+demoNotice()+`<div class="neighbor-list">${neighborFarms.filter(f=>f.city===city).map(f=>`<a class="neighbor-card" href="#visit-${f.id}"><div class="neighbor-card-art"><img src="art/imported/${f.house}.svg" alt=""><span>${f.avatar}</span><div class="neighbor-mini">${neighborBeds(f).slice(0,5).map(b=>`<i>${b.covered?'🏡':b.crop==='Огурцы'?'🥒':b.crop==='Томаты'?'🍅':'🌿'}</i>`).join('')}</div></div><div class="neighbor-card-info"><small>ДЕМО · ${esc(f.owner)}</small><h2>${f.name}</h2><p>${f.description}</p><div class="neighbor-tags"><span>${f.count} грядок</span><span>${f.covers} теплиц</span><span>Сезон · 6 месяцев</span></div><b>Зайти в хозяйство →</b></div></a>`).join('')}</div>`}
function neighborPlant(b){if(!['growing','planted','harvest_ready'].includes(b.state))return '';const art=b.state==='harvest_ready'&&/Томаты|Морковь/.test(b.crop)?`<img src="art/imported/${b.crop==='Томаты'?'tomato-single':'carrot2'}.svg" alt="">`:cropDrawing(b.crop,b.state);return Array.from({length:6},()=>`<i>${art}</i>`).join('')}
function visitNeighbor(id){const f=neighborFarms.find(f=>f.id===id);if(!f)return neighborCities();return `<a class="room-back" href="#farms-${f.city}">← Хозяйства · ${neighborCity(f.city).name}</a><div class="neighbor-heading"><span>${f.avatar}</span><div><small>В ГОСТЯХ · ДЕМО-ХОЗЯЙСТВО</small><h1>${f.name}</h1><p>${f.owner} · ${neighborCity(f.city).name} · пример шестимесячного сезона</p></div></div>${demoNotice()}<section class="neighbor-world" aria-label="Демонстрационное хозяйство ${f.name}"><div class="neighbor-buildings"><img src="art/imported/${f.house}.svg" alt="Дом хозяйства"><img src="art/imported/farm_house_lvl3.svg" alt="Демонстрационный склад"><img src="art/truck.svg" alt="Машина доставки"></div><div class="neighbor-beds">${neighborBeds(f).map(b=>`<button class="neighbor-bed ${b.covered?'covered':''}" onclick="neighborBed('${f.id}',${b.id})" aria-label="${b.covered?'Теплица':'Грядка'} ${b.id}: ${b.crop}, ${growingLabels[b.state]}"><span class="neighbor-soil"><span class="neighbor-plants">${neighborPlant(b)}</span>${b.covered?'<span class="neighbor-glass"></span>':''}</span><b>${b.covered?'Теплица':'Грядка'} №${b.id}</b><span>${b.crop}</span><small>${growingLabels[b.state]}</small></button>`).join('')}</div></section><section class="panel neighbor-season"><h2>История сезона</h2><p class="note">Сценарий для демонстрации: события и результаты вымышлены.</p><div>${[['Май','Первые грядки','Выбрали культуры и подготовили почву.'],['Июнь','Появились посадки','Посадили рассаду, согласовали уход.'],['Июль','Оборудовали хозяйство',`В сценарии установлено теплиц: ${f.covers}.`],['Август','Первая корзина','Собрали первые овощи и отправили домой.'],['Сентябрь','Продолжили сезон','Часть урожая отправилась на хранение.'],['Октябрь','Новый цикл','Подготовили освободившиеся грядки и защищённые посадки.']].map(([month,title,detail])=>`<article><small>${month}</small><h3>${title}</h3><p>${detail}</p></article>`).join('')}</div></section>`}
function neighborBed(id,number){const f=neighborFarms.find(f=>f.id===id),b=f&&neighborBeds(f).find(b=>b.id===number);if(!b)return;modalForm(`${b.covered?'Теплица':'Грядка'} №${b.id} · ${esc(f.name)}`,`<span class="pill">Демонстрационный участок</span><h3>${b.crop} · ${b.size} м²</h3><p>${growingLabels[b.state]}</p><p>${b.covered?'Посадки под прозрачным укрытием.':'Открытая грядка с посадками по плану сезона.'}</p><p>Вы в гостях: здесь можно рассмотреть пример хозяйства. Камера, заказы и покупки для демонстрационных грядок недоступны.</p><button type="button" class="btn" onclick="modal.close()">Вернуться в хозяйство</button>`,()=>{})}
const beforeNeighborRender=render;render=function(){beforeNeighborRender();const route=location.hash.slice(1);if(route==='farms'||route.startsWith('farms-')||route.startsWith('visit-')){const city=route.startsWith('farms-')?route.slice(6):neighborFarms.find(f=>'visit-'+f.id===route)?.city;$('#app').innerHTML=route==='farms'?neighborCities():route.startsWith('farms-')?neighborDirectory(city):visitNeighbor(route.slice(6));$('#crumb').textContent='КАРТА ФЕРМ';document.querySelectorAll('#game-dock a').forEach(a=>{if(a.hash==='#farms')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const header=document.querySelector('header>span:nth-child(2)');if(header)header.innerHTML=`<a class="city-switch" href="#farms">⌖ ${neighborCity(city)?.name||'Выбрать город'} ⌄</a>`}};render();
